        r"\bfunc\s+\([^\n)]{1,200}\)\s*([A-Za-z_]\w*)\s*\(",
        r"(?m)^[ \t]*([A-Za-z_][\w.-]*)[ \t]*[:=]",
        r'''\bid\s*=\s*["']([A-Za-z_][\w-]*)["']''',
    ]
